arguments.file_text:
namespace sv_f78a49e1b90644398eed3440f9288b0e.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_f78a49e1b90644398eed3440f9288b0e.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => SetActiveSection(section.Key)">
                    <span class="section-icon">@section.Value</span>
                    <span>@section.Key</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }
    </main>
</div>

@if (_toastMessage is not null)
{
    <div class="toast @_toastType">
        <span>@_toastMessage</span>
        <button @onclick="DismissToast">&times;</button>
    </div>
}

@if (_showConfirmDialog)
{
    <div class="dialog-overlay" @onclick="CancelConfirm">
        <div class="confirm-dialog" @onclick:stopPropagation="true">
            <h3>@_confirmTitle</h3>
            <p>@_confirmMessage</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool _loading;

    private readonly Dictionary<string, string> _sections = new()
    {
        ["Profile"] = "👤",
        ["Notifications"] = "🔔",
        ["Security"] = "🔒",
        ["Appearance"] = "🎨"
    };

    // Toast state
    private string? _toastMessage;
    private string _toastType = "success";

    // Confirm dialog state
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmCallback;

    // Profile state
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = new();
    private readonly List<string> _allChannels = new() { "general", "announcements", "random", "dev", "design", "marketing" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _editTheme = "System";
    private string _editFontSize = "Medium";
    private string _editLanguage = "en";
    private bool _editCompactMode;
    private readonly List<string> _languages = new() { "en", "es", "fr", "de", "ja", "zh" };
    private readonly Dictionary<string, string> _languageNames = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetActiveSection(string section)
    {
        ActiveSection = section;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        _loading = true;
        StateHasChanged();

        try
        {
            switch (ActiveSection)
            {
                case "Profile":
                    _savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfileFields();
                    break;
                case "Notifications":
                    _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    ResetNotificationFields();
                    break;
                case "Security":
                    _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    _changePasswordExpanded = false;
                    _currentPassword = "";
                    _newPassword = "";
                    _confirmPassword = "";
                    break;
                case "Appearance":
                    _appearanceSettings = await SettingsService.GetAppearanceAsync();
                    ResetAppearanceFields();
                    break;
            }
        }
        finally
        {
            _loading = false;
        }
    }

    // Profile methods
    private void ResetProfileFields()
    {
        if (_savedProfile is null) return;
        _editDisplayName = _savedProfile.DisplayName;
        _editEmail = _savedProfile.Email;
        _editAvatarUrl = _savedProfile.AvatarUrl;
        _editBio = _savedProfile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
    }

    // Notification methods
    private void ResetNotificationFields()
    {
        if (_notificationPrefs is null) return;
        _editEmailNotifications = _notificationPrefs.EmailNotifications;
        _editPushNotifications = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _editMutedChannels = new List<string>(_notificationPrefs.MutedChannels);
    }

    private void ToggleChannelMute(string channel)
    {
        if (_editMutedChannels.Contains(channel))
            _editMutedChannels.Remove(channel);
        else
            _editMutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId, string device)
    {
        _confirmTitle = "Revoke Session";
        _confirmMessage = $"Are you sure you want to revoke the session on \"{device}\"? This will sign out that device.";
        _confirmCallback = async () => await RevokeSession(sessionId);
        _showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked successfully.", "success");
    }

    private async Task ConfirmAction()
    {
        _showConfirmDialog = false;
        if (_confirmCallback is not null)
        {
            await _confirmCallback();
        }
    }

    private void CancelConfirm()
    {
        _showConfirmDialog = false;
        _confirmCallback = null;
    }

    // Appearance methods
    private void ResetAppearanceFields()
    {
        if (_appearanceSettings is null) return;
        _editTheme = _appearanceSettings.Theme;
        _editFontSize = _appearanceSettings.FontSize;
        _editLanguage = _appearanceSettings.Language;
        _editCompactMode = _appearanceSettings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearanceSettings = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = null;
    }

    // Render fragments for each section
    private RenderFragment ProfileSection => __builder =>
    {
        <h2>Profile Settings</h2>

        <div class="avatar-section">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                {
                    <img src="@_editAvatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
            </div>
            <div class="avatar-url">
                <label>Avatar URL</label>
                <input type="text" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="_editDisplayName" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="_editEmail" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea rows="4" @bind="_editBio"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment NotificationsSection => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editEmailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editPushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox" checked="@_editMutedChannels.Contains(channel)"
                           @onchange="() => ToggleChannelMute(channel)" />
                    <span>#@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment SecuritySection => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="security-panel">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
