        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        _loading = true;
        StateHasChanged();

        try
        {
            switch (ActiveSection)
            {
                case "Profile":
                    _savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfileFields();
                    break;
                case "Notifications":
                    _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    ResetNotificationFields();
                    break;
                case "Security":
                    _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    _changePasswordExpanded = false;
                    _currentPassword = "";
                    _newPassword = "";
                    _confirmPassword = "";
                    break;
                case "Appearance":
