+        @if (_loading)
+        {
+            <div class="loading-spinner">Loading...</div>
+        }
+        else
+        {
+            @switch (ActiveSection)
+            {
+                case "Profile":
+                    <ProfileSection />
+                    break;
+                case "Notifications":
+                    <NotificationsSection />
+                    break;
+                case "Security":
+                    <SecuritySection />
+                    break;
+                case "Appearance":
+                    <AppearanceSection />
+                    break;
+            }
+        }
+    </main>
+</div>
+
+@if (_toastMessage is not null)
+{
+    <div class="toast @_toastType">
+        <span>@_toastMessage</span>
+        <button @onclick="DismissToast">&times;</button>
+    </div>
+}
+
+@if (_showConfirmDialog)
+{
+    <div class="dialog-overlay" @onclick="CancelConfirm">
+        <div class="confirm-dialog" @onclick:stopPropagation="true">
+            <h3>@_confirmTitle</h3>
+            <p>@_confirmMessage</p>
+            <div class="dialog-actions">
+                <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
+                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string ActiveSection { get; set; } = "Profile";
+    private bool _loading;
+
+    private readonly Dictionary<string, string> _sections = new()
+    {
+        ["Profile"] = "👤",
+        ["Notifications"] = "🔔",
+        ["Security"] = "🔒",
+        ["Appearance"] = "🎨"
