+    private readonly Dictionary<string, string> _languageNames = new()
+    {
+        ["en"] = "English",
+        ["es"] = "Español",
+        ["fr"] = "Français",
+        ["de"] = "Deutsch",
+        ["ja"] = "日本語",
+        ["zh"] = "中文"
