+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadSectionData();
+    }
+
+    private async Task SetActiveSection(string section)
+    {
+        ActiveSection = section;
+        await LoadSectionData();
+    }
+
+    private async Task LoadSectionData()
+    {
+        _loading = true;
+        StateHasChanged();
+
+        try
+        {
+            switch (ActiveSection)
+            {
+                case "Profile":
+                    _savedProfile = await SettingsService.GetProfileAsync();
+                    ResetProfileFields();
+                    break;
+                case "Notifications":
+                    _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
+                    ResetNotificationFields();
