+    color: #333;
+}
+
+.confirm-dialog p {
+    margin: 0 0 1.25rem 0;
+    color: #555;
+    font-size: 0.9rem;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Loading */
+.loading-spinner {
